      "id": "dfb7e6b4fe5f0d784249fbeb15478bcb",
      "title": "만 18세~30세 남녀) 온라인/모바일 게임 유저 패널",
      "source": "naver_cafe",
      "source_url": "https://m.cafe.naver.com/togetheralba/128615",
