      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n9/9~10) 20~54세 여성) 국산 주류 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.31. 22:28\n조회 99\n구독\n9/9~10) 20~54세 남녀) 국산 주류 좌담회\n○ 만 20~54세 남녀\n○ 평소 국산 주류를 즐겨 드시는 분\n○ 그룹1 (9/9일(수) 4시) : 20-24세 대학생 남/여\n○ 그룹2 (9/9일(수) 7시) : 25-29세 직장인 미혼 남/여 (프리랜서 포함)\n○ 그룹3 (9/10일(목) 4시) : 35-54세 직장인 기혼 남/여 (프리랜서, 전업주부 포함)\n○ 그룹4 (9/10일(목) 7시) : 30-34세 직장인 기미혼 남/여\n○ 조사 장소 : 충정로역\n○ 조사 방식 : 120~150분 좌담회\n○ 사례비 : 5만원\n▶ 아래 질문에 응답해주세요\n1. 이름\n2. 전화번호\n3. 성별\n4. 거주지(OO구 OO동)\n5. 직업(직장명/업종/부서명, 학교/학과/학년 등 구체적으로)\n6. 나이(생년월일)\n7. 지난 1개월 동안 드셔보신 국산 주류/브랜드 (예: 맥주/카스, 소주/참이슬 등)\nhttps://forms.gle/Pc3vVUcJp2dwMs7E9\n9/9~10) 20~54세 남녀) 국산 주류 좌담회\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n9/29~30) 15~25만) 25~54세) 최근 2년 내에 Volvo 구매자 좌담회\n좌담회알바좌담회카페\n26.08.31.\n댓글\n0\n9/9~10) 20~54세 여성) 국산 주류 좌담회\n좌담회알바좌담회카페\n26.08.31.\n댓글\n0\n9/9~10) 20~54세 남성) 국산 주류 좌담회\n좌담회알바좌담회카페\n26.08.31.\n댓글\n0\n9/15~21) 만20~69세 여성 )26년 2월 이후 출시 로봇 청소기 구매자 조사\n좌담회알바좌담회카페\n26.08.31.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
